import csv
import json
import re
import pandas as pd
import numpy as np

CSV_PATH = r"D:\Anuj\Pearl-ASsignment\amazon-products.csv"
df_raw = pd.read_csv(CSV_PATH, dtype=str, keep_default_na=False)

print("=== 1. DETAILED PLACEHOLDER BREAKDOWN ===")
placeholder_patterns = {
    "empty_str ('')": lambda s: s == "",
    "whitespace_only": lambda s: s != "" and s.strip() == "",
    "literal 'null'": lambda s: s.strip().lower() == "null",
    "literal 'None'": lambda s: s.strip() == "None",
    "literal 'NA'/'N/A'": lambda s: s.strip().upper() in ("NA", "N/A"),
    "literal 'NaN'": lambda s: s.strip().lower() == "nan",
    "literal '-'": lambda s: s.strip() in ("-", "--"),
    "empty JSON '[]'": lambda s: s.strip() == "[]",
    "empty JSON '{}'": lambda s: s.strip() == "{}",
}

cols_with_placeholders = []
for col in df_raw.columns:
    col_counts = {}
    for p_name, func in placeholder_patterns.items():
        c = int(df_raw[col].apply(func).sum())
        if c > 0:
            col_counts[p_name] = c
    if col_counts:
        cols_with_placeholders.append((col, col_counts, sum(col_counts.values())))

cols_with_placeholders.sort(key=lambda x: x[2], reverse=True)
for col, counts, total in cols_with_placeholders:
    details = ", ".join([f"{k}: {v}" for k, v in counts.items()])
    print(f"{col:<25} Total: {total:>4} ({total/10:.1f}%) | {details}")

print("\n=== 2. DEEP DIVE INTO MIXED TYPE COLUMNS ===")
mixed_cols = [
    "initial_price", "final_price", "domain", "date_first_available", 
    "discount", "model_number", "upc", "asin", "description", 
    "variations", "features", "delivery", "buybox_prices", "seller_name"
]

for col in mixed_cols:
    s = df_raw[col]
    # Filter out empty/placeholder
    non_empty = s[~s.apply(lambda v: any(func(v) for func in placeholder_patterns.values()))]
    print(f"\n--- Column: {col} (non-empty count: {len(non_empty)}) ---")

    # Classify each
    val_types = Counter()
    sample_by_type = {}
    for v in non_empty:
        v_str = v.strip()
        t = "other"
        if re.match(r"^-?\d+$", v_str):
            t = "pure_int"
        elif re.match(r"^-?\d+\.\d+$", v_str):
            t = "pure_float"
        elif re.match(r'^"+-?\d+(\.\d+)?"+$', v_str):
            t = "quoted_number"
        elif v_str.startswith("$") or re.match(r'^\$?\d{1,3}(,\d{3})*(\.\d+)?$', v_str):
            t = "formatted_currency"
        elif v_str.lower() in ("true", "false"):
            t = "boolean"
        elif (v_str.startswith("[") and v_str.endswith("]")):
            t = "json_list"
        elif (v_str.startswith("{") and v_str.endswith("}")):
            t = "json_dict"
        elif v_str.startswith("http://") or v_str.startswith("https://"):
            t = "url"
        elif re.match(r"^\d{4}-\d{2}-\d{2}", v_str) or re.match(r"^[A-Z][a-z]+ \d{1,2}, \d{4}", v_str):
            t = "date_string"
        else:
            t = "text_alphanumeric"

        val_types[t] += 1
        if t not in sample_by_type:
            sample_by_type[t] = []
        if len(sample_by_type[t]) < 3:
            sample_by_type[t].append(v_str[:60])

    for t, count in val_types.most_common():
        print(f"  Type '{t}': {count} ({count/len(non_empty)*100:.1f}%) | Samples: {sample_by_type[t]}")

print("\n=== 3. ANOMALIES & SPECIAL CHARACTER ARTIFACTS ===")
# Check for Unicode block characters (e.g. \u2588) or redactions, corrupted UTF-8
for col in df_raw.columns:
    block_chars = df_raw[col].apply(lambda s: bool(re.search(r"[\u2580-\u259F]", str(s)))).sum()
    if block_chars > 0:
        print(f"Column '{col}' has {block_chars} rows with block characters (redaction \u2588)!")
        samples = df_raw[col][df_raw[col].apply(lambda s: bool(re.search(r"[\u2580-\u259F]", str(s))))].head(3).tolist()
        print(f"  Samples: {samples}")

# Check for triple quotes or unusual quoting
for col in df_raw.columns:
    triple_quotes = df_raw[col].apply(lambda s: '"""' in str(s) or s.startswith('"')).sum()
    if triple_quotes > 0:
        print(f"Column '{col}' has {triple_quotes} rows with internal or redundant quotes!")
        samples = df_raw[col][df_raw[col].apply(lambda s: '"""' in str(s) or s.startswith('"'))].head(3).tolist()
        print(f"  Samples: {samples}")

